import {installCaptureGuide} from './torres-guide.js';
import {normalizeTour} from './torres-tour-data.js'; import {imageDataUrl} from './image-upload.js';
export function initTourEditor({form,node,api,notify}){
 let exterior=[],scenes=[],uploading=false,generation=0;const section=node('section','tour-editor');section.innerHTML='<label class="tour-enable"><input type="checkbox" id="tour-enabled"> Habilitar Torres 360 en esta publicación</label><div class="tour-editor-body" hidden><h2>Prepara su Torres 360</h2><p>La experiencia se construye con fotografías de esta unidad. Exterior en secuencia; interior con panoramas reales o fotos de detalle.</p><details><summary>Guía de fotografías que necesitamos</summary><ol><li><b>Exterior:</b> ideal 36 fotos horizontales (mínimo 8, máximo 72). Mismo centro, distancia, altura y luz; auto cerrado, ruedas rectas. Empieza de frente y rodea el vehículo en sentido horario. Nombra 01, 02…36.</li><li><b>Interior:</b> panoramas esféricos completos 360° × 180°, formato equirectangular 2:1 (por ejemplo 4096 × 2048), desde los asientos delanteros y traseros. Usa cámara 360° o una aplicación que exporte una esfera completa; el modo panorámico habitual del celular no basta.</li><li><b>Detalles:</b> fotos normales del tablero, maletero, motor u otros puntos. Se mostrarán como fotos, sin deformarlas.</li><li>Sin personas, datos personales ni reflejos del fotógrafo. JPG, PNG o WebP, hasta 8 MB por imagen. Antes de publicar revisa la vista previa.</li></ol></details><h3>Giro exterior</h3><label>Cargar secuencia (se ordena por nombre)<input id="tour-exterior" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="tour-exterior-list"></div><h3>Interior y puntos de interés</h3><div class="fields"><label>Nombre de la vista<input id="tour-scene-label" placeholder="Asientos delanteros, tablero, maletero…" maxlength="70"></label><label>Tipo de imagen<select id="tour-scene-kind"><option value="panorama">Panorama esférico 360° · proporción 2:1</option><option value="photo">Fotografía normal de detalle</option></select></label></div><label>Añadir imagen de esta vista<input id="tour-scene-file" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="tour-scenes-list"></div><button type="button" id="tour-preview">Previsualizar Torres 360</button><div class="tour-admin-preview" hidden></div><p role="status" class="tour-upload-status"></p></div>';
 form.querySelector('.vehicle-video-editor').before(section);const enabled=section.querySelector('#tour-enabled'),body=section.querySelector('.tour-editor-body'),status=section.querySelector('.tour-upload-status'),preview=section.querySelector('.tour-admin-preview');enabled.onchange=()=>{body.hidden=!enabled.checked;preview.replaceChildren();preview.hidden=true;};
 const guide=installCaptureGuide(section,node,()=>({exterior,scenes}));const button=(text,fn)=>{const b=node('button','',text);b.type='button';b.onclick=fn;return b;};
 function draw(){const list=section.querySelector('.tour-exterior-list');list.replaceChildren();exterior.forEach((url,i)=>{const row=node('div','tour-photo-row'),img=node('img');img.src=url;img.alt='Toma '+(i+1);row.append(img,node('span','',String(i+1).padStart(2,'0')),button('Antes',()=>{if(i){[exterior[i-1],exterior[i]]=[exterior[i],exterior[i-1]];draw();}}),button('Después',()=>{if(i<exterior.length-1){[exterior[i+1],exterior[i]]=[exterior[i],exterior[i+1]];draw();}}),button('Quitar',()=>{exterior.splice(i,1);draw();}));list.append(row);});const views=section.querySelector('.tour-scenes-list');views.replaceChildren();scenes.forEach((s,i)=>{const row=node('div','tour-photo-row'),img=node('img');img.src=s.photo;img.alt=s.label;const label=node('input');label.value=s.label;label.maxLength=70;label.setAttribute('aria-label','Nombre de vista '+(i+1));label.oninput=()=>s.label=label.value;row.append(img,label,node('span','',s.kind==='panorama'?'360°':'Foto'),button('Quitar',()=>{scenes.splice(i,1);draw();}));views.append(row);});preview.replaceChildren();preview.hidden=true;guide.refresh();}
 async function upload(file,panorama=false){if(file.size>8*1024*1024)throw Error('Máximo 8 MB por imagen.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usa JPG, PNG o WebP.');if(panorama){const bmp=await createImageBitmap(file);const ratio=bmp.width/bmp.height;bmp.close();if(Math.abs(ratio-2)>.025)throw Error('Un panorama esférico debe medir el doble de ancho que de alto (2:1). Usa Foto de detalle si es una foto normal.');}const image=await imageDataUrl(file);return(await api('admin/upload','POST',{image})).url;}
 async function run(input,action){if(uploading)return;uploading=true;section.querySelectorAll('input[type=file],#tour-preview').forEach(n=>n.disabled=true);status.textContent='Subiendo fotografías… espera antes de guardar.';try{const current=generation;await action(current);if(current!==generation)return;draw();status.textContent='Fotos listas. Guarda el vehículo para conservar Torres 360.';}catch(e){status.textContent=e.message;notify(e.message,{type:'error'});}finally{uploading=false;input.value='';section.querySelectorAll('input[type=file],#tour-preview').forEach(n=>n.disabled=false);}}
 section.querySelector('#tour-exterior').onchange=e=>run(e.target,async(current)=>{const files=[...e.target.files].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));if(files.length+exterior.length>72)throw Error('Máximo 72 fotos exteriores.');for(const file of files){const url=await upload(file);if(current!==generation)return;exterior.push(url);}});
 section.querySelector('#tour-scene-file').onchange=e=>run(e.target,async(current)=>{if(scenes.length>=8)throw Error('Máximo 8 vistas interiores o de detalle.');const label=section.querySelector('#tour-scene-label').value.trim(),kind=section.querySelector('#tour-scene-kind').value;if(!label)throw Error('Escribe el nombre de esta vista.');const file=e.target.files[0];if(file){const photo=await upload(file,kind==='panorama');if(current!==generation)return;scenes.push({label,kind,photo});}});
 section.querySelector('#tour-preview').onclick=async()=>{try{const tour=normalizeTour({enabled:true,exterior,scenes});const {createTorresTour}=await import('./torres-tour.js');preview.replaceChildren(createTorresTour(tour,node));preview.hidden=false;}catch(e){notify(e.message,{type:'error'});}};
 return{open(v){generation++;exterior=[...(v?.torres360?.exterior||[])];scenes=(v?.torres360?.scenes||[]).map(s=>({...s}));enabled.checked=v?.torres360?.enabled===true;body.hidden=!enabled.checked;draw();guide.reset();status.textContent='';},capture(){if(uploading)throw Error('Espera a que terminen de subir las fotos de Torres 360.');return normalizeTour({enabled:enabled.checked,exterior,scenes});}};
}
